// Takes the dish photo from the form and stores it under one predictable binary name: photo.
const form = $('When Dish Photo Submitted').first();
const photo = Object.values(form.binary || {}).find(b => String(b.mimeType || '').startsWith('image/'));
const ext = { 'image/png': 'png', 'image/webp': 'webp' };
return [{
  json: {
    file_name: photo.fileName || `dish.${ext[photo.mimeType] || 'jpg'}`,
    mime_type: photo.mimeType || 'image/jpeg',
  },
  binary: { photo },
}];

// Reads the photo's pixel size from its file header (JPEG, PNG, WebP) and plans a centered 9:16 crop.
// Kling 3.0 has no aspect-ratio input: the video takes its shape from the photo, so a 9:16 photo gives a vertical Reel.
const s = $('Configure Video Settings').first().json;
const target = 9 / 16;
const cropOn = s.crop_to_vertical === true || s.crop_to_vertical === 'true';

function exifOrientation(buf, t) {
  const le = buf.toString('ascii', t, t + 2) === 'II';
  const u16 = o => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = o => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const ifd = t + u32(t + 4);
  const count = u16(ifd);
  for (let k = 0; k < count; k++) {
    const e = ifd + 2 + k * 12;
    if (u16(e) === 0x0112) return u16(e + 8);
  }
  return 1;
}

function imageSize(buf) {
  try {
    if (buf[0] === 0x89 && buf.toString('ascii', 1, 4) === 'PNG') {
      return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20), orientation: 1 };
    }
    if (buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP') {
      const kind = buf.toString('ascii', 12, 16);
      if (kind === 'VP8X') return { w: 1 + buf.readUIntLE(24, 3), h: 1 + buf.readUIntLE(27, 3), orientation: 1 };
      if (kind === 'VP8L') { const b = buf.readUInt32LE(21); return { w: (b & 0x3fff) + 1, h: ((b >> 14) & 0x3fff) + 1, orientation: 1 }; }
      if (kind === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff, orientation: 1 };
    }
    if (buf[0] === 0xff && buf[1] === 0xd8) {
      let i = 2;
      let orientation = 1;
      while (i + 9 < buf.length) {
        if (buf[i] !== 0xff) { i++; continue; }
        const marker = buf[i + 1];
        if (marker === 0xff) { i++; continue; }
        if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8)) { i += 2; continue; }
        const len = buf.readUInt16BE(i + 2);
        if (marker === 0xe1 && buf.toString('ascii', i + 4, i + 8) === 'Exif') {
          try { orientation = exifOrientation(buf, i + 10) || 1; } catch (e) { orientation = 1; }
        }
        if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
          return { w: buf.readUInt16BE(i + 7), h: buf.readUInt16BE(i + 5), orientation };
        }
        i += 2 + len;
      }
    }
  } catch (e) {}
  return null;
}

const item = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'photo');
const size = imageSize(buf);
let crop = { x_percent: 0, y_percent: 0, width_percent: 100, height_percent: 100 };
let problem = null;
let w = null;
let h = null;
if (!size || !size.w || !size.h) {
  problem = `The dish photo (${item.json.file_name}) could not be read. Use a JPG, PNG or WebP photo.`;
} else {
  // EXIF orientations 5-8 mean the phone stored the photo rotated by 90 degrees.
  const rotated = size.orientation >= 5 && size.orientation <= 8;
  w = rotated ? size.h : size.w;
  h = rotated ? size.w : size.h;
  const ratio = w / h;
  if (cropOn && ratio > target * 1.01) {
    const wp = (target / ratio) * 100;
    crop = { x_percent: Math.round(((100 - wp) / 2) * 1000) / 1000, y_percent: 0, width_percent: Math.round(wp * 1000) / 1000, height_percent: 100 };
  } else if (cropOn && ratio < target * 0.99) {
    const hp = (ratio / target) * 100;
    crop = { x_percent: 0, y_percent: Math.round(((100 - hp) / 2) * 1000) / 1000, width_percent: 100, height_percent: Math.round(hp * 1000) / 1000 };
  }
  const outW = (w * crop.width_percent) / 100;
  const outH = (h * crop.height_percent) / 100;
  if (outW < 300 || outH < 300) problem = `The dish photo is too small: Kling needs at least 300 x 300 px after cropping (got ${Math.round(outW)} x ${Math.round(outH)}).`;
  if (!cropOn && (ratio < 0.4 || ratio > 2.5)) problem = `The dish photo has an aspect ratio Kling does not accept (0.4 to 2.5).`;
}
return [{ json: { ...item.json, width: w, height: h, ...crop, size_problem: problem }, binary: item.binary }];

// fal returned an upload URL. Put the photo back next to it for the upload step.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const photo = $('Design Vertical Crop for Photo').first();
const res = $input.first().json || {};
return [{
  json: {
    ...photo.json,
    upload_url: res.upload_url || '',
    file_url: res.file_url || '',
    upload_error: res.upload_url ? '' : errText(res.error) || 'no upload URL returned',
  },
  binary: photo.binary,
}];

// Makes sure the photo is on fal and cropped, then picks the plan: OpenAI prompts or the template prompts.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Configure Video Settings').first().json;
const p = $('Setup Photo for fal Upload').first().json;
const put = $('Upload Photo to fal Storage').first().json || {};
const crop = $input.first().json || {};
const url = crop.image && crop.image.url;
const problems = [];
if (p.size_problem) problems.push(p.size_problem);
else if (p.upload_error) problems.push(`fal storage did not return an upload URL (${p.upload_error}).`);
else if (put.error) problems.push(`Upload to fal storage failed (${errText(put.error)}).`);
else if (!url) problems.push(`fal could not crop the photo (${errText(crop.error) || errText(crop.detail) || 'no image URL returned'}).`);
if (problems.length) return [{ json: { route: 'error', ok: false, stage: 'Dish photo', problems } }];
const useAi = s.use_openai === true || s.use_openai === 'true';
return [{ json: { route: useAi ? 'ai' : 'template', ok: true, file_name: p.file_name, image_url: url } }];

