// Builds the one Kling request (1-3 shots in a single clip) and the caption for every network.
// The AI label line and your footer are added here, so every caption carries them.
const s = $('Configure Video Settings').first().json;
const f = $('When Dish Photo Submitted').first().json;
const photo = $('Validate Photo on fal').first().json;
const aiRan = $('Create Shot Prompts and Captions').isExecuted;
const ai = aiRan ? (($input.first().json && $input.first().json.output) || {}) : {};
const clean = v => String(v ?? '').trim();
const dish = clean(f['Dish Name']);
const model = clean(s.video_model);
const isV3 = /kling-video\/v3\//.test(model);
const isV4 = /kling-video\/v4\//.test(model);

// ---- shots: Kling 3.0 takes 3-15 s in total and 1-15 s per shot
const shotCount = Math.min(3, Math.max(1, Math.round(Number(s.shot_count) || 1)));
const total = Math.min(15, Math.max(3, shotCount, Math.round(Number(s.video_seconds) || 10)));
const base = Math.floor(total / shotCount);
const durations = Array.from({ length: shotCount }, (_, i) => base + (i < total - base * shotCount ? 1 : 0));
const guard = clean(s.prompt_guardrails);
const templateShots = [s.shot_1_prompt, s.shot_2_prompt, s.shot_3_prompt].map(t => clean(t).split('{dish}').join(dish || 'dish'));
const aiShots = Array.isArray(ai.shots) ? ai.shots.map(x => clean(typeof x === 'string' ? x : x && x.prompt)) : [];
// Kling 4.0 caps each shot prompt at 512 characters; Kling 3.0 at 2500 for the whole prompt.
const cap = isV4 ? 512 : 1200;
let fallbacks = 0;
const shots = durations.map((d, i) => {
  let text = aiShots[i];
  if (!text) { fallbacks++; text = templateShots[i] || templateShots[0]; }
  return { prompt: `${text.slice(0, Math.max(80, cap - guard.length - 1))} ${guard}`.trim().slice(0, cap), duration: d };
});
let promptSource = 'template shots';
if (aiRan) promptSource = fallbacks === 0 ? 'OpenAI' : (fallbacks === shotCount ? 'template shots (OpenAI returned none)' : `OpenAI (${fallbacks} shot(s) from the template)`);

// ---- fal request (field names from the fal OpenAPI schema of the endpoint in video_model)
const body = { start_image_url: photo.image_url };
if (shots.length === 1) {
  body.prompt = shots[0].prompt;
  body.duration = isV3 ? String(total) : total;
} else {
  body.multi_prompt = shots.map(x => ({ prompt: x.prompt, duration: isV3 ? String(x.duration) : x.duration }));
  if (isV3) { body.duration = String(total); body.shot_type = 'customize'; }
}
const audio = s.generate_audio === true || s.generate_audio === 'true';
if (isV3) {
  body.generate_audio = audio;
  body.negative_prompt = clean(s.negative_prompt);
  body.cfg_scale = Number(s.cfg_scale);
}

// ---- captions: only facts typed into the form
const about = clean(f['Ingredients']);
const price = clean(f['Price']);
const when = clean(f['Availability']);
const business = clean(f['Business Name']);
const where = clean(f['Location or Link']);
const tags = clean(s.extra_hashtags);
const firstTag = (tags.match(/#[^\s#]+/) || [''])[0];
const tail = [clean(s.ai_label_line), clean(s.business_footer)].filter(Boolean).join('\n');
const head = business ? `${dish} at ${business}` : dish;
const offer = [price, when].filter(Boolean).join(' | ');
const template = {
  tiktok: [head, about, offer, tags].filter(Boolean).join('\n'),
  instagram: [head, about, offer, where, tags].filter(Boolean).join('\n\n'),
  facebook: [head, about, offer, where].filter(Boolean).join('\n\n'),
  threads: [head, offer, where, firstTag].filter(Boolean).join('\n'),
};
const pick = (key, aiKey, max) => {
  const body = clean(ai[aiKey]) || template[key];
  const room = Math.max(0, max - tail.length - 2);
  return `${body.slice(0, room).trim()}\n\n${tail}`.trim();
};
const captions = {
  tiktok: pick('tiktok', 'tiktok_caption', 2200),
  instagram: pick('instagram', 'instagram_caption', 2200),
  facebook: pick('facebook', 'facebook_caption', 5000),
  threads: pick('threads', 'threads_caption', 500),
  source: clean(ai.tiktok_caption) ? 'OpenAI' : 'template',
};

return [{
  json: {
    model,
    body,
    shots: shots.length,
    total_seconds: total,
    generate_audio: isV3 ? audio : null,
    captions,
    prompt_source: promptSource,
    visible_dish: clean(ai.visible_dish),
  },
}];

// The video job must have a request id from fal before polling starts.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const j = $input.first().json || {};
if (!j.request_id || !j.status_url || !j.response_url) {
  return [{ json: { ok: false, stage: 'Kling submit', problems: [`fal did not accept the video job (${errText(j.error) || errText(j.detail) || 'no request id'}).`] } }];
}
return [{
  json: {
    ok: true,
    request_id: j.request_id,
    status_url: j.status_url,
    response_url: j.response_url,
    cancel_url: j.cancel_url || `${j.response_url}/cancel`,
    submitted_at: Date.now(),
  },
}];

// Decides one state for the job: done, failed, timed_out, or running (check again).
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Configure Video Settings').first().json;
const job = $('Verify Video Job Queued').first().json;
const c = $input.first().json || {};
const minutes = (Date.now() - Number(job.submitted_at || Date.now())) / 60000;
const status = c.status || 'UNKNOWN';
const problems = [];
let state = 'running';
if (!c.status && c.error) { state = 'failed'; problems.push(`Status check failed (${errText(c.error)}).`); }
else if (status === 'COMPLETED' && c.error) { state = 'failed'; problems.push(`Kling failed on fal: ${errText(c.error)}${c.error_type ? ` [${c.error_type}]` : ''}`); }
else if (status === 'COMPLETED') state = 'done';
else if (minutes > Number(s.timeout_minutes)) { state = 'timed_out'; problems.push(`Kling took longer than ${s.timeout_minutes} minutes (last status ${status}).`); }
return [{ json: { ...job, status, state, stage: 'Kling render', queue_position: c.queue_position ?? null, minutes_elapsed: Math.round(minutes * 10) / 10, problems } }];

// Checks the finished file before it goes to SocialRobot. Duration comes from the MP4 header (mvhd box).
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Configure Video Settings').first().json;
const plan = $('Build Kling Video Request').first().json;
const result = $('Retrieve Video Result from fal').first().json || {};
const item = $input.first();
const video = item.binary && item.binary.data;
const problems = [];
let sizeMb = 0;
let seconds = null;
if (!result.video || !result.video.url) {
  problems.push(`Kling finished but fal returned no video (${errText(result.error) || errText(result.detail) || 'empty response'}).`);
} else if (!video) {
  problems.push(`The video could not be downloaded from fal (${errText(item.json.error) || 'no file'}).`);
} else {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  sizeMb = buf.length / 1048576;
  const i = buf.indexOf('mvhd');
  if (i > 3) {
    const v1 = buf[i + 4] === 1;
    const scale = buf.readUInt32BE(i + (v1 ? 24 : 16));
    const units = v1 ? Number(buf.readBigUInt64BE(i + 28)) : buf.readUInt32BE(i + 20);
    if (scale) seconds = Math.round((units / scale) * 10) / 10;
  }
  const type = String(video.mimeType || '');
  if (!/video\/(mp4|quicktime)/.test(type) && !/\.(mp4|mov)$/i.test(video.fileName || '')) problems.push(`Unexpected file type ${type || 'unknown'}.`);
  if (sizeMb > Number(s.max_file_mb)) problems.push(`File is ${sizeMb.toFixed(1)} MB, above the ${s.max_file_mb} MB limit.`);
  if (seconds === null) problems.push('Could not read the video duration.');
  else if (Math.abs(seconds - Number(plan.total_seconds)) > Number(s.duration_tolerance_seconds)) problems.push(`Video is ${seconds} s; expected ${plan.total_seconds} s.`);
  else if (seconds < 3) problems.push(`Video is ${seconds} s; Reels need at least 3 s.`);
}
return [{
  json: { ok: problems.length === 0, stage: 'Video check', problems, size_mb: Math.round(sizeMb * 100) / 100, duration_seconds: seconds, video_url: (result.video && result.video.url) || '' },
  binary: item.binary,
}];

// One readable reason for whatever went wrong. Add an error workflow in the workflow settings to get alerts.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const f = $('When Dish Photo Submitted').first();
const j = $input.first().json || {};
let message;
if ($('Cancel fal Video Job').isExecuted) {
  const src = $('Assess Video Job Status').first().json;
  message = `Kling video stopped (${src.stage || 'Kling'}): ${(src.problems || []).join(' ')} The unfinished fal job was sent a cancel request.`;
} else if (Array.isArray(j.problems) && j.problems.length) {
  message = `${j.stage || 'Check'} failed: ${j.problems.join(' ')}`;
} else if (j.error && $('Draft TikTok Food Video').isExecuted) {
  message = `SocialRobot could not save the TikTok draft: ${errText(j.error)}`;
} else if (!$('Organize Dish Photo').isExecuted) {
  message = 'Upload one photo of the dish (JPG, PNG or WebP).';
} else {
  message = `Unexpected failure: ${JSON.stringify(j).slice(0, 500)}`;
}
return [{ json: { message, dish: f.json['Dish Name'] || '' } }];
